export function airportLabel(a: Airport): string {
  return `(${a.iata}) ${a.city}, ${a.country}`;
}

export function findAirportByCode(code: string): Airport | undefined {
  const c = code.trim().toUpperCase();
  return AIRPORTS.find((a) => a.iata === c || a.icao === c);
}